pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {L1Block} from "../src/L1Block.sol";

contract InvMutTest is Test {
    L1Block c;
    function setUp() public { c = new L1Block(); }
    function testRegression_property() public {
        uint64 _number = 10;
        uint64 _timestamp = 100;
        uint256 _basefee = 200;
        bytes32 _hash = bytes32(uint256(12345));
        uint64 _sequenceNumber = 1;
        bytes32 _batcherHash = bytes32(uint256(2));
        uint256 _l1FeeOverhead = 300;
        uint256 _l1FeeScalar = 400;

        vm.prank(0xDeaDDEaDDeAdDeAdDEAdDEaddeAddEAdDEAd0001);
        c.setL1BlockValues(_number, _timestamp, _basefee, _hash, _sequenceNumber, _batcherHash, _l1FeeOverhead, _l1FeeScalar);

        assertTrue(c.hash() == _hash);
    }
}
